<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{session}from'../api';import{enterpriseApi}from'../services/enterprise'
const bootstrap=ref<any>(null),usage=ref<any>(null),settings=ref<any>(null),loading=ref(true),saving=ref(false),error=ref(''),notice=ref('');const form=reactive({name:'',short_name:'',contact:'',timezone:'Asia/Shanghai'})
const features=computed(()=>Object.entries(bootstrap.value?.features||{}).map(([code,value])=>({code,...(value as any)}))),opened=computed(()=>features.value.filter(x=>x.enabled)),closed=computed(()=>features.value.filter(x=>!x.enabled)),trials=computed(()=>opened.value.filter(x=>x.source==='trial'))
const canEdit=computed(()=>session.role==='owner'),expiryState=computed(()=>{const value=settings.value?.subscription?.expires_at;if(!value)return'未设置到期时间';const days=Math.ceil((new Date(value).getTime()-Date.now())/86400000);return days<0?'订阅已到期':days<=30?`${days} 天后到期`:`有效至 ${String(value).slice(0,10)}`})
async function load(){loading.value=true;error.value='';try{[bootstrap.value,usage.value,settings.value]=await Promise.all([enterpriseApi.bootstrap(),enterpriseApi.usage(),enterpriseApi.settings()]);Object.assign(form,settings.value.organization);session.bootstrap=bootstrap.value}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function save(){if(!canEdit.value)return;saving.value=true;try{const result=await enterpriseApi.saveSettings(form);await load();notice.value=`企业资料已保存，配置版本更新为 ${result.config_version}。客户端将在下一次 Bootstrap 同步。`}catch(e:any){error.value=`保存失败：${e.message}`}finally{saving.value=false}}
onMounted(load)
</script>
<template><div class="page-stack"><div v-if="loading" class="panel skeleton detail-skeleton"></div><div v-else-if="error&&!settings" class="panel state-panel error"><span class="state-icon">!</span><h3>企业设置暂时不可用</h3><p>{{error}}</p><button class="primary" @click="load">重新加载</button></div><template v-else><section class="subscription-hero"><div><span class="eyebrow light">SUBSCRIPTION & CONFIGURATION</span><h2>{{settings.organization.name}}</h2><p>{{settings.organization.plan_code}} 套餐 · {{expiryState}}</p></div><div><span>CONFIG VERSION</span><strong>{{settings.config_version}}</strong><small>企业与客户端统一配置版本</small></div></section><div v-if="notice" class="success-banner">{{notice}}</div><div v-if="error" class="form-error">{{error}}</div><section class="panel"><header class="panel-head"><div><h3>企业资料</h3><p>用于企业后台识别和时区展示，不会发送到 TikTok。</p></div><button v-if="canEdit" class="primary" :disabled="saving" @click="save">{{saving?'保存中…':'保存企业资料'}}</button></header><div class="profile-form"><label>企业全称<input v-model="form.name" :disabled="!canEdit"></label><label>企业简称<input v-model="form.short_name" :disabled="!canEdit"></label><label>联系人<input v-model="form.contact" :disabled="!canEdit"></label><label>企业时区<select v-model="form.timezone" :disabled="!canEdit"><option value="Asia/Shanghai">Asia/Shanghai</option><option value="America/Los_Angeles">America/Los_Angeles</option><option value="America/New_York">America/New_York</option><option value="Europe/London">Europe/London</option><option value="Asia/Tokyo">Asia/Tokyo</option></select></label></div></section><section class="panel"><header class="panel-head"><div><h3>限制与用量</h3><p>服务端执行额度校验，页面状态仅用于清晰展示。</p></div><span class="plan">{{settings.organization.plan_code}}</span></header><div class="usage-grid"><article v-for="(x,key) in usage"><span>{{String(key)==='devices'?'设备':String(key)==='rooms'?'直播间':'成员'}}</span><strong>{{x.used}} / {{x.limit}}</strong><i><em :style="{width:`${Math.min(100,x.used/Math.max(1,x.limit)*100)}%`}"></em></i><small>{{x.used>=x.limit?'额度已满':'仍可继续使用'}}</small></article></div></section><section class="panel"><header class="panel-head"><div><h3>客户端配置</h3><p>这些参数由服务端统一下发，企业端只读，防止设备自行偏离策略。</p></div></header><div class="config-grid"><article><span>心跳间隔</span><b>{{settings.client_config.heartbeat_interval_seconds}} 秒</b></article><article><span>离线队列上限</span><b>{{settings.client_config.heartbeat_queue_max_items}} 条</b></article><article><span>离线队列保留</span><b>{{settings.client_config.heartbeat_queue_max_age_hours}} 小时</b></article><article><span>最低客户端版本</span><b>{{settings.client_config.minimum_client_version}}</b></article><article><span>报告保留</span><b>{{bootstrap.features.report_center?.config?.retention_days||bootstrap.features.report_center?.limits?.retention_days||'按套餐策略'}}</b></article><article><span>订阅宽限期</span><b>{{settings.subscription.grace_ends_at?.slice(0,10)||'未设置'}}</b></article></div></section><section class="panel"><header class="panel-head"><div><h3>已开通功能</h3><p>试用、套餐、企业覆盖和版本限制均已计算为最终值。</p></div><div class="chip-row"><span class="source-chip enabled">已开通 {{opened.length}}</span><span v-if="trials.length" class="source-chip trial">试用中 {{trials.length}}</span><span class="source-chip disabled">未开通 {{closed.length}}</span></div></header><div class="feature-grid"><article v-for="x in opened" :key="x.code"><span class="feature-check">✓</span><div><b>{{x.name}}</b><small>{{x.source}}<template v-if="x.source==='trial'"> · 试用中</template></small></div></article></div><div v-if="closed.length" class="feature-grid muted section-gap"><article v-for="x in closed" :key="x.code"><span class="feature-check">—</span><div><b>{{x.name}}</b><small>{{x.reason==='minimum_version'?'客户端版本过低':x.reason||'未开通'}}</small></div></article></div></section></template></div></template>
